# COLORS
G = "\033[92m"
C = "\033[96m"
R = "\033[91m"
Y = "\033[93m"
W = "\033[97m"
D = "\033[2m"
B = "\033[1m"
RESET = "\033[0m"

HOST = "127.0.0.1"
PORT = 8765

server = None
server_thread = None

# MUSIC
MUSIC_FILE = None   # temp file, created from the embedded song
music_proc = None


def start_music():
    """Start the song in the background (loops). Only starts once."""
    global music_proc, MUSIC_FILE

    if music_proc is not None and music_proc.poll() is None:
        return

    # Extract the embedded song to a temp file (once)
    if MUSIC_FILE is None or not os.path.isfile(MUSIC_FILE):
        try:
            tmp = tempfile.NamedTemporaryFile(
                delete=False, suffix=".mp3", prefix="ghostscout_"
            )
            tmp.write(base64.b64decode(MUSIC_B64))
            tmp.close()
            MUSIC_FILE = tmp.name
        except Exception:
            return

    players = [
        ("mpg123", ["mpg123", "-q", "--loop", "-1", MUSIC_FILE]),
        ("ffplay", ["ffplay", "-nodisp", "-autoexit", "-loop", "0",
                    "-loglevel", "quiet", MUSIC_FILE]),
        ("mpv", ["mpv", "--no-video", "--loop=inf",
                 "--really-quiet", MUSIC_FILE]),
        ("cvlc", ["cvlc", "--no-video", "--loop", "--quiet", MUSIC_FILE]),
    ]

    for name, cmd in players:
        if shutil.which(name):
            try:
                music_proc = subprocess.Popen(
                    cmd,
                    stdin=subprocess.DEVNULL,
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                )
                return
            except OSError:
                continue


def stop_music():
    global music_proc, MUSIC_FILE

    if music_proc is not None and music_proc.poll() is None:
        music_proc.terminate()
        try:
            music_proc.wait(timeout=2)
        except subprocess.TimeoutExpired:
            music_proc.kill()

    music_proc = None

    if MUSIC_FILE is not None and os.path.isfile(MUSIC_FILE):
        try:
            os.remove(MUSIC_FILE)
        except OSError:
            pass
    MUSIC_FILE = None


atexit.register(stop_music)


# CLEAR TERMINAL
def clear():
    os.system("clear" if os.name == "posix" else "cls")


# MATRIX RAIN
def matrix_rain(duration=2):
    chars = "01ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    width = shutil.get_terminal_size((80, 24)).columns

    end = time.time() + duration

    while time.time() < end:
        line = "".join(
            random.choice(chars + "   ")
            for _ in range(width)
        )
        print(G + line + RESET)
        time.sleep(0.06)

    clear()


# BANNER
def banner():
    print(G + B + r"""
   _____ _   _  ____  _____ _____ _____ _____
  / ____| | | |/ __ \ / ____/ ____|_   _|
 | |  __| |_| | |  | | (___| |      | |
 | | |_ |  _  | |  | |\___ \ |      | |
 | |__| | | | | |__| |____) | |_____| |_
  \_____|_| |_|\____/|_____/_____/|_____|

       G H O S T S C O U T
    ADVANCED CYBER TERMINAL
""" + RESET)

    print(C + "       KALI LINUX EDITION V3.0" + RESET)
    print()


# BOOT ANIMATION
def boot():
    clear()
    banner()

    messages = [
        "Initializing interface",
        "Loading terminal modules",
        "Checking Python runtime",
        "Preparing local dashboard",
        "Loading visual components",
        "GHOSTSCOUT READY"
    ]

    for msg in messages:
        print(G + "[  OK  ] " + RESET + msg)
        time.sleep(0.25)

    print()
    time.sleep(0.4)


# SYSTEM INFORMATION
def system_info():
    clear()

    print(G + B + "[ SYSTEM INTELLIGENCE ]" + RESET)

    print(C + "Hostname  : " + RESET + socket.gethostname())
    print(C + "Platform  : " + RESET + platform.platform())
    print(C + "Processor : " + RESET + platform.machine())
    print(C + "Python    : " + RESET + platform.python_version())
    print(C + "Time      : " + RESET + datetime.now().strftime("%Y-%m-%d %H:%M:%S"))

    if sys.platform.startswith("linux"):
        print(C + "\n[ LOCAL NETWORK INTERFACES ]" + RESET)

        if shutil.which("ip"):
            os.system("ip -brief address")
        else:
            print("Command 'ip' unavailable.")

    input("\nPress ENTER to continue...")


